focusRules:
@media (max-width: 760px) {
  .seller-sidebar { position: relative; z-index: 30; display: grid; grid-template-columns: minmax(0px, 1fr) auto; align-items: center; gap: 12px; padding: 12px 14px; }
  .seller-mobile-nav-toggle { display: inline-flex; min-width: 96px; min-height: 44px; align-items: center; justify-content: center; padding: 10px 12px; border: var(--line); background: var(--lime); color: var(--ink); font: 700 11px "Space Mono"; text-transform: uppercase; cursor: pointer; }
  .seller-mobile-nav-toggle:focus-visible { outline: 3px solid var(--cobalt); outline-offset: 2px; }
  .seller-sidebar > .status-badge { display: none; }
  .seller-sidebar nav[data-mobile-nav] { position: absolute; top: calc(100% + 1px); left: 14px; right: 14px; z-index: 40; display: grid; gap: 4px; max-height: min(70vh, 560px); overflow-y: auto; padding: 8px; border: var(--line); background: var(--surface); box-shadow: var(--shadow); }
  .seller-sidebar nav[data-mobile-nav="closed"] { display: none; }
  .seller-sidebar nav[data-mobile-nav="open"] { display: grid; }
  .seller-sidebar nav[data-mobile-nav] a { display: flex; min-height: 44px; align-items: center; padding: 10px 12px; }
  .seller-sidebar nav[data-mobile-nav] a[aria-current="page"] { background: var(--lime); border-color: var(--ink); box-shadow: 2px 2px 0 var(--ink); color: var(--ink); }
  .seller-dashboard .seller-sidebar { position: relative; top: auto; height: auto; min-height: 0px; grid-template-columns: minmax(0px, 1fr) auto; gap: 12px; border-right: 0px; border-bottom: var(--line); }
}

